use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur: string = ""
        let mut inq = false
        let chars: Vec<char> = line.chars().collect()
        let n: int = chars.len() as int
        let mut i: int = 0
        while i < n {
            let c = chars[i]
            if inq {
                if c == '"' {
                    if i + 1 < n && chars[i + 1] == '"' {
                        cur.push('"')
                        i += 1
                    } else {
                        inq = false
                    }
                } else {
                    cur.push(c)
                }
            } else {
                if c == '"' {
                    inq = true
                } else if c == ',' {
                    fields.push(cur)
                    cur = ""
                } else if c != '\r' {
                    cur.push(c)
                }
            }
            i += 1
        }
        fields.push(cur)
        let parts: Vec<string> = fields.map(|f| "[${f}]").collect()
        println("${fields.len()}: ${parts.join("|")}")
    }
}

